import{_ as r,l,o as a,c as i,v as t,p as o,x as c,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"延迟测量 cyclictest","description":"","frontmatter":{"title":"延迟测量 cyclictest","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/latency-measurement.md","filePath":"cs/latency-measurement.md","lastUpdated":1789023840000}'),h={name:"cs/latency-measurement.md"};function m(_,e,u,f,T,E){const s=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="延迟测量-cyclictest" tabindex="-1">延迟测量 cyclictest <a class="header-anchor" href="#延迟测量-cyclictest" aria-label="Permalink to &quot;延迟测量 cyclictest&quot;">​</a></h1><div class="epigraph"><p>cyclictest 按设定周期醒来，记录「应当醒来」与「实际醒来」之差，画出内核调度与抢占延迟的尾部。</p><footer>—— 据 rt-tests 的 cyclictest 文档；OSADL 对实时 Linux 测量的实践</footer></div><p><a href="/cs/preempt-rt">PREEMPT_RT</a> 声称有界。<a href="/cs/eevdf">EEVDF</a> 声称尾延迟更好。缺口是 <strong>怎么量</strong>：cyclictest 测的是唤醒延迟，不是应用业务延迟。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任务 <code>clock_nanosleep</code> 到点，看 now-expected。直方图：max 才是 RT 关心的。缺口：必须隔核、关 HT、注意 <a href="/cs/napi">NAPI</a> 与 ksoftirqd；tracer 本身扰动。本课不把 OSADL 农场的全部配置复制过来。</p><p><span class="marginnote">用户循环里的计时要用 CLOCK_MONOTONIC_RAW 一类，避免 NTP 跳。对象是调度延迟，不是网卡 RTT。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>绑 FIFO 高优先级 → 周期性睡眠 → 记录差。对照 <a href="/cs/perf-sampling">perf</a> 后课：perf 看热点，cyclictest 看最坏唤醒。对照 <a href="/cs/blkio-cgroup">blkio</a>：I/O 负载是扰动源，应同时加压。对照 fsync：那是存储完成，不是 CPU 唤醒。</p>',8)),(a(),o(d,null,{default:c(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SL%5B%22nanosleep%20%E5%88%B0%E7%82%B9%22%5D%20--%3E%20WK%5B%22%E8%A2%AB%E8%B0%83%E5%BA%A6%E4%B8%8A%20CPU%22%5D%0A%20%20WK%20--%3E%20D%5B%22now%20-%20%E9%A2%84%E6%9C%9F%22%5D%0A%20%20D%20--%3E%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%E4%B8%8E%20max%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>测量把「实时」从口号变成分布。没有加压的 max 没有意义。不要写成示波器使用课。与 <a href="/cs/tickless-nohz">tickless</a> 后课：无 tick 会改变唤醒路径，测量要注明模式。</p><p>结果不可在虚拟机与裸机间直接比，除非声明半虚拟时钟。</p><p>实现上：无负载的 cyclictest 只测空闲路径，要同时用 hackbench 或网络打满。虚拟机里测的是宿主注入，不是裸机。CLOCK_MONOTONIC 可能含 NTP 调整，测抖动用 RAW。 读法上只引用<a href="/cs/preempt-rt">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>延迟测量 cyclictest</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 tracing 事件。不保证手机 SoC 的数字可移植。下一课用 cgroup 管 CPU 组：组调度。</p><p>版本字段会变，课序钉的是机制对象「延迟测量 cyclictest」，不是某一主线内核的结构体名。 后课默认：唤醒延迟可用周期睡眠直方图刻画。cgroup cpu 控制器如何摊权重与限额，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cyclictest 量周期唤醒误差的尾部。</li><li>必须加压与绑核才有解释力。</li><li>cgroup CPU 组调度是下一课。</li><li>出处：rt-tests cyclictest；OSADL；POSIX 时钟。</li></ul>',11))])}const y=r(h,[["render",m]]);export{A as __pageData,y as default};
